const source={mutualism:'https://insektentrainer.nabu.de/insekt/steinhummel/',dispersal:'https://www.waldwissen.net/de/lebensraum-wald/tiere-im-wald/voegel/markwart-der-vorlaute-eichenpflanzer',evolution:'https://openstax.org/books/biology-2e/pages/19-2-population-genetics'};
const communitySource='https://openstax.org/books/biology-2e/pages/45-6-community-ecology';
export const INTERACTION_TERMS={
 parasitism:{title:'Parasitismus (Ektoparasitismus)',classification:'Antagonistische Wirts-Parasit-Beziehung',definition:'Ein Parasit entzieht einem lebenden Wirt Nahrung. Er profitiert, während dem Wirt Ressourcen verloren gehen oder Gewebeschäden entstehen.',effect:'Parasit + · Wirt −',proof:'Bestimme Wirt und Parasit. Beobachte die Anheftung und laufende Nahrungsaufnahme; im Modell steigt die aufgenommene Nahrung des Parasiten und die Ressourcenbelastung des Wirts.',limit:'Die Nahrungskosten sind didaktische Modellwerte, keine Messung an Wildtieren. Die längere Saugphase ist dargestellt; Wirtswechsel, vollständiger Lebenszyklus und Krankheitserreger werden nicht simuliert.'},
 predation:{title:'Räuber-Beute-Beziehung (Prädation)',classification:'Trophische Interaktion',definition:'Ein Räuber nutzt ein anderes Tier als Nahrung. Wahrnehmung, Verfolgung und Flucht entscheiden mit über den Jagderfolg.',effect:'Räuber + · Beute −',proof:'Beobachte den Räuber mit einem tatsächlich verfolgten Beutetier oder einem dokumentierten Fang.',limit:'Ein Jagdversuch beweist keine Populationsschwankung. Lotka-Volterra beschreibt Populationen unter vereinfachenden Annahmen.'},
 competition:{title:'Konkurrenz (interspezifisch)',classification:'Antagonistische Interaktion',definition:'Verschiedene Arten beanspruchen dieselbe begrenzte Ressource und verringern damit gegenseitig ihre Nutzungsmöglichkeiten.',effect:'Art A − · Art B −',proof:'Beide Arten müssen denselben endlichen Nahrungsvorrat nutzen und aufeinander reagieren.',limit:'Bloße räumliche Nähe ist kein Konkurrenznachweis. Innerhalb derselben Art spricht man von intraspezifischer Konkurrenz.'},
 mutualism:{title:'Mutualismus: Bestäubung',classification:'Wechselseitiger Nutzen',definition:'Beide Arten profitieren: Das Insekt gewinnt Nahrung; Pollentransport ermöglicht der Pflanze sexuelle Fortpflanzung.',effect:'Insekt + · Pflanze +',proof:'Verfolge ein Insekt zwischen zwei Pflanzen derselben Art. Erst tatsächliche Pollenübertragung zählt.',limit:'Ein einzelner Blütenbesuch genügt nicht. Befruchtung und Samenbildung werden hier noch nicht simuliert; Bestäubung ist nicht automatisch eine dauerhafte Symbiose.'},
 herbivory:{title:'Herbivorie (Pflanzenfraß)',classification:'Trophische Interaktion',definition:'Ein Tier frisst lebendes Pflanzengewebe. Die Pflanze verliert Biomasse, der Pflanzenfresser erhält Nahrung.',effect:'Pflanzenfresser + · Pflanze −',proof:'Beobachte Fraß an einer konkreten Pflanze, deren modellierter Nahrungsvorrat abnimmt.',limit:'Herbivorie muss die Pflanze nicht töten. Wiederholtes Fressen und Nachwachsen werden hier als Vorrat abgebildet.'},
 dispersal:{title:'Zoochorie (Samenverbreitung)',classification:'Transport durch Tiere',definition:'Tiere verbreiten Samen. Bei Vorratsverstecken können nicht wiedergefundene Samen an einem neuen Ort keimen.',effect:'Gegenseitiger Nutzen möglich',proof:'Beobachte Samenaufnahme, Transport und Verstecken an einem anderen Ort.',limit:'Zoochorie ist nicht immer Mutualismus. Aufnahme und Transport sind sichtbar; erfolgreiche Keimung und Etablierung werden noch nicht nachgewiesen.'},
 deposit:{title:'Detritivorie (Detritusfraß)',classification:'Trophische Beziehung zu Detritus',definition:'Tiere nutzen abgestorbenes organisches Material als Nahrung und tragen zu dessen Zerkleinerung bei.',effect:'Detritus → Detritivor',proof:'Beobachte eine passende Art bei der Aufnahme organischer Partikel oder Laubstreu.',limit:'Detritivorie ist von der weiteren mikrobiellen Zersetzung und Mineralisierung zu unterscheiden. Sedimentaufnahme allein beweist keine vollständige Destruktion.'},
 filtering:{title:'Filtration (Ernährungsweise)',classification:'Nahrungsaufnahme aus Wasser',definition:'Filtrierer entnehmen dem Wasser Nahrungspartikel, etwa Plankton oder organische Schwebstoffe.',effect:'Schwebstoffe → Filtrierer',proof:'Beobachte eine lebende Muschel bei tatsächlicher Wasserbedeckung und aktiver Filtration.',limit:'Filtration bezeichnet eine Ernährungsweise, keinen eigenen Wechselwirkungstyp. Leere Schalen und trockenliegende Muscheln belegen keine laufende Filtration.'},
 resourceUse:{title:'Ökologische Nische: Ressourcennutzung',classification:'Ökologisches Konzept',definition:'Die ökologische Nische beschreibt Ansprüche und Beziehungen einer Art, einschließlich Nahrung, Teilraum und Aktivitätszeit.',effect:'Nahrung · Teilraum · Suchweise',proof:'Bestimme die Art und beobachte ihre tatsächliche Nahrungsaufnahme. Vergleiche die genutzten Ressourcen.',limit:'Die Nische ist kein Ort. Ein einzelner Nahrungsfund beschreibt nur einen Teil der Nische und beweist weder Konkurrenz noch Nischentrennung.'}
};
export const QUESTS=[
 {id:'fox-mouse',category:'interaction',kind:'predation',title:'Jagd im Unterholz',habitat:'forest',species:['fox','apodemus_sylvaticus'],question:'Wie reagieren Jäger und Beute aufeinander?',goal:'Bestimme den Fuchs und beobachte eine echte Verfolgung oder einen Fang sechs Sekunden lang.',concept:'Räuber–Beute · Wahrnehmung · Flucht · Energiegewinn'},
 {id:'shared-leaves',category:'interaction',kind:'competition',title:'Zwei Pflanzenfresser, eine Ressource',habitat:'meadow',species:['hare','capreolus_capreolus'],question:'Wie unterscheidet sich Konkurrenz von Prädation?',goal:'Finde die beiden Pflanzenfresser an derselben Nahrungsstelle und beobachte das Konkurrenzverhalten.',concept:'Interspezifische Konkurrenz · begrenzte Ressourcen'},
 {id:'pollen-transfer',category:'interaction',kind:'mutualism',title:'Nektar gegen Pollentransport',habitat:'meadow',species:['bombus_lapidarius','trifolium_pratense'],question:'Woran erkennst du, dass beide Partner profitieren?',goal:'Folge dem Bestäuber von einer Blüte zur nächsten. Der Nachweis entsteht nach einer tatsächlichen Pollenübertragung zwischen zwei Pflanzen derselben Art.',concept:'Mutualismus · Bestäubung · Fortpflanzung',source:source.mutualism},
 {id:'browse',category:'interaction',kind:'herbivory',title:'Blätter werden zu Tierbiomasse',habitat:'forest',species:['capreolus_capreolus','corylus_avellana'],question:'Welche trophische Beziehung siehst du hier?',goal:'Beobachte ein Reh beim Fressen an einer konkreten Pflanze. Ihr modellierter Nahrungsvorrat nimmt dabei ab.',concept:'Herbivorie · Produzenten und Primärkonsumenten'},
 {id:'acorn-cache',category:'interaction',kind:'dispersal',title:'Der Eichelhäher als Samenverteiler',habitat:'forest',species:['garrulus_glandarius','quercus_robur'],question:'Wieso kann ein Vorratsversteck der Eiche nützen?',goal:'Beobachte, wie ein Eichelhäher einen Samen aufnimmt, wegträgt und an einem anderen Ort versteckt. Nicht jedes Versteck wird zu einem Baum.',concept:'Zoochorie · Vorratshaltung · bedingter gegenseitiger Nutzen',source:source.dispersal},
 {id:'litter-network',category:'interaction',kind:'deposit',title:'Leben von abgestorbenem Material',habitat:'forest',species:['lumbricus_terrestris'],question:'Warum ist ein Regenwurm kein Produzent?',goal:'Suche einen Regenwurm in der Laubstreu und beobachte die Aufnahme organischen Materials.',concept:'Detritivorie · Zerkleinerung · Stoffkreislauf'},
 {id:'tidal-filter',category:'interaction',kind:'filtering',title:'Filtrierer im Takt der Tide',habitat:'wadden',species:['mytilus_edulis'],question:'Wieso ist bei Ebbe nicht dieselbe Aktivität zu sehen?',goal:'Finde eine lebende Miesmuschel im Wasser und beobachte Filtration. Leere Schalen reichen für diese Aufgabe nicht.',concept:'Filtration · Plankton · abiotischer Faktor Wasserstand'}
];
for(const q of QUESTS){q.encounters=INTERACTION_CASES[q.kind];q.title=({predation:'Räuber und Beute',competition:'Konkurrenz um gemeinsame Ressourcen',mutualism:'Mutualismus: Pollen und Nektar',herbivory:'Pflanzen werden zu Tierbiomasse',dispersal:'Samen transportieren und verstecken',deposit:'Detritus im Nahrungsnetz',filtering:'Filtration im Wasser'})[q.kind];q.goal=({predation:'Bestimme einen Räuber und beobachte eine tatsächliche Verfolgung oder einen Fang. Vergleiche anschließend andere Lebensräume.',competition:'Beobachte zwei Arten an derselben Nahrungsstelle. Beide nutzen den endlichen Vorrat und reagieren aufeinander.',herbivory:'Beobachte Blattfraß an einer bestimmten Pflanze. Ihr modellierter Vorrat nimmt dabei ab.',dispersal:'Beobachte Samenaufnahme, Transport und Verstecken. Nicht jedes Versteck wird zu einem Baum.',deposit:'Beobachte die Aufnahme abgestorbenen organischen Materials in Wald, Gewässer oder Küstensaum.',filtering:'Beobachte eine lebende Muschel bei Wasserbedeckung. Leere Schalen reichen für die Aufgabe nicht.'})[q.kind]||q.goal;}
for(const [factor,data]of Object.entries(EVOLUTION_FACTORS))QUESTS.push({id:`evolution-${factor}`,category:'evolution',kind:factor,title:data.name,encounters:EVOLUTION_ENCOUNTERS.filter(e=>e.factor===factor).map(e=>({...e,id:`${e.habitat}:${e.species}`,species:[e.species]})),question:data.question,goal:data.explanation,concept:'Population · Vererbung · Allelhäufigkeiten',source:source.evolution});
export const SPECIES_FOCUS=assignFocus(QUESTS);
for(const s of Object.values(ANIMALS))if(s.parasite)SPECIES_FOCUS[s.id]='parasitism';
const others=Object.values(ANIMALS).filter(s=>!SPECIES_FOCUS[s.id]&&!s.parasite);
const resourceQuest={id:'food-niches',category:'interaction',kind:'resourceUse',title:'Nahrungssuche und ökologische Nischen',question:'Welche Nahrung und welchen Teilraum nutzt diese Art?',goal:'Bestimme die Art und beobachte ihre tatsächliche Nahrungsaufnahme an einer endlichen Ressource oder an lebender Beute. Vergleiche Körperbau und Suchweise.',concept:'Ökologische Nische · Ressourcennutzung · trophische Rolle',encounters:others.flatMap(s=>s.habitats.map(habitat=>({id:`${habitat}:${s.id}`,habitat,species:[s.id]})))};
QUESTS.push(resourceQuest);Object.assign(SPECIES_FOCUS,assignFocus([resourceQuest]));
for(const q of QUESTS)if(q.category==='interaction'){Object.assign(q,INTERACTION_TERMS[q.kind]);q.source=q.source||communitySource;}

export class QuestBook {
 constructor(simulations,evolution,storage=null){this.simulations=simulations;this.evolution=evolution;this.storage=storage;this.active=null;this.completed={};try{this.completed=JSON.parse(storage?.getItem('feldbuch-quests-v1')||'{}').completed||{};}catch{}}
 save(){try{this.storage?.setItem('feldbuch-quests-v1',JSON.stringify({completed:this.completed}));}catch{}}
 available(){return this.scenario?.current?.quests||QUESTS;}
 select(id){const q=this.available().find(q=>q.id===id);if(!q)throw Error('Unknown quest');this.cancel();if(q.category==='evolution')this.evolution.start(q.kind);
  const contexts=q.scenario?this.scenario.contexts(q):q.encounters.map(e=>{const sim=this.simulations.get(e.habitat),model=q.category==='evolution'?this.evolution.activeModels?.find(m=>m.sim.habitat===e.habitat&&m.species===e.species[0])||this.evolution:null;
   const context=model?{actors:model.adults().map(a=>a.id)}:sim.relations.arm(q.kind,e.species);return {...e,...(context||{actors:[]}),model,unavailable:!context,started:sim.time,seconds:0,done:false,evidence:null};});
  const alreadyDone=q.scenario&&this.progress(q)>0;if(alreadyDone)contexts.forEach(c=>c.done=true);
  this.active={quest:q,contexts,context:contexts.find(c=>!c.unavailable)||contexts[0],seconds:0,watched:0,done:!!alreadyDone,preferredHabitat:null};return this.active;
 }
 cancel(){if(!this.scenario?.current)for(const sim of this.simulations.values())sim.relations.clearIntent();this.evolution.stop();this.active=null;}
 actor(c,observer){if(c.unavailable)return null;const sim=this.simulations.get(c.habitat),eligible=x=>c.species.includes(x.species)&&!x.dead&&!x.scenarioInactive&&!x.scenarioSuppressed&&(x.alive||x.surveySpecimen&&x.sampleSpot);return c.model?c.model.focusAgent(observer):sim.agents.find(x=>x.id===c.actor&&eligible(x))||sim.agents.find(x=>c.actors.includes(x.id)&&eligible(x));}
 target(observer){const a=this.active;if(!a||a.done)return null;const distance=p=>Math.hypot((p.renderX??p.x+(p.offsetX||0))-observer.x,(p.renderZ??p.z+(p.offsetZ||0))-observer.z);
  const found=a.contexts.filter(c=>!c.done).map(c=>({c,p:this.actor(c,observer)})).filter(r=>r.p).sort((x,y)=>(Number(y.c.id===a.preferredContext)-Number(x.c.id===a.preferredContext))||(Number(y.c.habitat===a.preferredHabitat)-Number(x.c.habitat===a.preferredHabitat))||distance(x.p)-distance(y.p))[0];
  if(!found)return null;a.context=found.c;if(found.c.model)this.evolution.selectedModel=found.c.model;return found.p;
 }
 partners(){const a=this.active;if(!a||a.done)return[];const result=[],seen=new Set();
  for(const c of a.contexts.filter(c=>!c.done&&!c.unavailable)){
   const sim=this.simulations.get(c.habitat),allowed=new Set(c.species),actors=sim.agents.filter(x=>x.alive&&!x.dead&&!x.scenarioInactive&&!x.scenarioSuppressed&&allowed.has(x.species)&&(c.model?c.model.pool.includes(x):c.actors.includes(x.id)));
   for(const x of actors){const key=`${c.habitat}:${x.id}`;if(!seen.has(key)){seen.add(key);result.push(x);}}
   const p=a.quest.scenario?c.group?.plan?.patch||c.patch:actors[0]?.hiveWorker?actors[0].targetResource||c.patch:c.patch||actors[0]?.targetResource;
   if(p&&PLANTS[p.species]&&allowed.has(p.species)){const key=`${c.habitat}:${p.species}:${p.x}:${p.z}`;if(!seen.has(key)){seen.add(key);result.push({...p,habitat:c.habitat,focusType:'plant'});}}
  }return result;
 }
 validEncounter(actor,c=this.active.context,q=this.active.quest){const e=actor.lastEvent,age=e?actor.age-(e.age??e.time):Infinity;
  if(q.kind==='predation'){const prey=actor.target;if((actor.encounterPlan?actor.liveHunt&&actor.lastMoved>=this.simulations.get(actor.habitat).time-.4:actor.activity==='hunting'&&actor.speed>.01)&&prey?.alive&&ANIMALS[actor.species].prey.includes(prey.species)&&c.actors.includes(prey.id)&&Math.hypot(actor.x-prey.x,actor.z-prey.z)<28)return{kind:'pursuit',actor:actor.id,other:prey.species};}
  if(!e||e.time<c.started||age<0||age>14)return null;if(q.kind==='predation'&&['predation','huntAttempt','escape'].includes(e.kind)&&c.actors.includes(e.otherId))return e;
  if(q.kind==='resourceUse'&&actor.id===c.actor&&['feeding','herbivory','predation','deposit','filtering','flowerVisit'].includes(e.kind))return e;
  if(e.kind===q.kind&&(!['competition','parasitism'].includes(q.kind)||c.actors.includes(e.otherId))&&(!q.scenario||!PLANTS[q.species[1]]||e.other===q.species[1]))return e;return null;
 }
 observe(focus,dt,journal,visible=null){if(this.scenario?.current)return this.scenario.observe(focus,dt,journal,this,visible);const a=this.active;if(!a||a.done)return null;const actor=focus?.type==='animal'?focus.item:null,c=actor&&a.contexts.find(c=>!c.done&&c.habitat===actor.habitat&&(c.model?c.model.pool.includes(actor):c.actors.includes(actor.id)));
  if(!c||actor.trace||!actor.alive||!journal.entries[actor.species]){a.seconds=0;a.observationKey=null;for(const c of a.contexts)c.seconds=0;return null;}
  const key=`${c.id}:${actor.id}`;if(a.observationKey!==key){for(const candidate of a.contexts)candidate.seconds=0;a.observationKey=key;}a.context=c;a.watched+=dt;const evidence=c.model?(c.model.evidence(a.quest.kind)?c.model.report():null):this.validEncounter(actor,c);
  if(!evidence){c.seconds=0;a.seconds=0;return null;}c.seconds+=dt;a.seconds=c.seconds;c.evidence=evidence;if(c.seconds<6)return null;
  c.done=true;const old=this.completed[a.quest.id]||{},records=old.encounters||{};records[c.id]={completedAt:Date.now(),habitat:c.habitat,evidence};this.completed[a.quest.id]={...old,completedAt:Date.now(),encounters:records};this.save();a.done=a.contexts.every(c=>c.done);return{kind:'quest',quest:a.quest,habitat:c.habitat,allDone:a.done};
 }
 progress(q){return Object.keys(this.completed[q.id]?.encounters||{}).length;}
 export(){return{scenario:this.scenario?.current?.id||null,completed:this.completed,active:this.active?{id:this.active.quest.id,done:this.active.done}:null};}
}
export function questSpecies(q){return q.species.map(id=>ANIMALS[id]?.common||PLANTS[id]?.common||id);}
